Item.method_code:
using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
{
Innovator inn = this.getInnovator();
Item newItem = this;
string id = newItem.getID();
string newState = newItem.getProperty("h4_directaplist","");
string oldStateId = newItem.getProperty("current_state");
Item stateItem = inn.getItemById("Life Cycle State", oldStateId);
string oldStateName = stateItem.getProperty("name");
string lockedById = newItem.getProperty("locked_by_id");
string currentUserId = inn.getUserID();
bool unlockFlag = false;
if(newState != oldStateName)
{
    if(newItem.getLockStatus() == 1)
    {
        newItem.unlockItem();
        unlockFlag = true;
    }
    switch (newState)
    {
        case "InProgress":
        newItem.promote("InProgress","Promote message");
        break;
        case "InReview":
        newItem.promote("InReview","Promote message");
        break;
        case "ProvisionalApproved":
        newItem.promote("ProvisionalApproved","Promote message");
        break;
        case "RequestApproval":
        newItem.promote("RequestApproval","Promote message");
        break;
        case "Approved":
        newItem.promote("Approved","Promote message");
        break;
    }
        
    if(unlockFlag)
    {
        newItem.lockItem();
    }
}
return this;
}
